out = []
for ko,en,cont,cko,cen,clat,clon,pop,info,cities in D:
    out.append({
        "country_ko": ko, "country_en": en, "continent": cont,
        "capital": {"name_ko": cko, "name_en": cen, "lat": clat, "lon": clon},
        "major_cities": [{"name_ko": c[0], "name_en": c[1], "lat": c[2], "lon": c[3]} for c in cities],
        "population": pop,
        "key_info_ko": info,
    })

with open("data/world_countries.json", "w", encoding="utf-8") as f:
    json.dump(out, f, ensure_ascii=False, indent=2)

total_points = sum(1 + len(c["major_cities"]) for c in out)
print("countries:", len(out), "total points:", total_points)
